import { describe, expect, it } from "vitest";
import snapshotFixture from "../fixtures/core-snapshot-v1.json";
import {
  selectCapabilities, selectDomain, selectIntegrations, selectRuntime, selectSources,
} from "./projection";
import type { ControlSnapshot } from "./types";

// The fixture is generated by packages/velvetos_control_api/snapshot.py in Core,
// with no contributions and a frozen clock. It contains no production data.
const envelope = snapshotFixture as ControlSnapshot;

describe("live Core v1 snapshot envelope contract", () => {
  it("requires the exact canonical schema and consumed top-level types", () => {
    expect(envelope.schema).toBe("velvetos.control.v1");
    expect(typeof envelope.generatedAt).toBe("string");
    expect(typeof envelope.flags).toBe("object");
    expect(envelope.flags).not.toBeNull();
    expect(typeof envelope.freshness).toBe("object");
    expect(envelope.freshness).not.toBeNull();
    expect(typeof (envelope.freshness as Record<string, unknown>).state).toBe("string");
    expect(["modules", "capabilities", "integrations", "health", "attention", "activity"]
      .every((key) => Array.isArray(envelope[key]))).toBe(true);
    expect(envelope.collections).not.toBeNull();
    expect(typeof envelope.collections).toBe("object");
  });

  it("preserves unavailable Core collections without inventing items", () => {
    const collections = envelope.collections as Record<string, Record<string, unknown>>;
    for (const key of ["production", "content", "files", "agents", "models", "jobs"]) {
      expect(collections).toHaveProperty(key);
      expect(collections[key].state).toBe("unknown");
      expect(collections[key].items).toBeNull();
      const selected = selectDomain(envelope, key);
      expect(selected.state).toBe("unknown");
      expect(selected.items).toBeNull();
    }
    expect(selectCapabilities(envelope).items).toEqual([]);
    expect(selectIntegrations(envelope).items).toEqual([]);
    expect(selectRuntime(envelope).items).toEqual([]);
    expect(selectSources(envelope).state).toBe("ready");
  });

  it("fails closed for a mismatched Core schema at all projection entries", () => {
    const incompatible = { ...envelope, schema: "velvetos.control.v2" };
    expect(selectDomain(incompatible, "jobs").state).toBe("unknown");
    expect(selectCapabilities(incompatible).items).toBeNull();
    expect(selectIntegrations(incompatible).items).toBeNull();
    expect(selectSources(incompatible).items).toBeNull();
    expect(selectRuntime(incompatible).items).toBeNull();
  });
});
